frappe.ui.form.on('Vital Signs', {
    validate: function(frm) {

        if(!frm.doc.temperature) return;

        let temp = frm.doc.temperature.toString()
            .replace("F","")
            .replace("C","")
            .trim();

        let value = parseFloat(temp);

        if(isNaN(value)) return;

        if(value >= 95){
            frm.set_value("temperature", value + " F");
        }
        else if(value <= 45){
            frm.set_value("temperature", value + " C");
        }

    }
});

frappe.ui.form.on('Review', {
    visited_date: function(frm, cdt, cdn) {
        calculate_next_visit(frm, cdt, cdn);
    },
    days: function(frm, cdt, cdn) {
        setTimeout(function() {
            calculate_next_visit(frm, cdt, cdn);
        }, 500);
    }
});

function calculate_next_visit(frm, cdt, cdn) {
    var row = locals[cdt][cdn];
    var visited_date = row.visited_date;
    var days = parseInt(row.days);

    if (!visited_date || !days || isNaN(days)) return;

    var parts      = visited_date.split('-');
    var year       = parseInt(parts[0]);
    var month      = parseInt(parts[1]) - 1;
    var day        = parseInt(parts[2]);
    var date_obj   = new Date(year, month, day);
    date_obj.setDate(date_obj.getDate() + days);

    var next_year  = date_obj.getFullYear();
    var next_month = String(date_obj.getMonth() + 1).padStart(2, '0');
    var next_day   = String(date_obj.getDate()).padStart(2, '0');
    var next_date  = next_year + '-' + next_month + '-' + next_day;

    frappe.model.set_value(cdt, cdn, 'next_visit_date', next_date);
    frm.refresh_field('Review');
}

frappe.ui.form.on('Patient', {
    after_save: function(frm) {
        var review_table = frm.doc.Review;
        if (!review_table || review_table.length === 0) return;

        // Show popup table after save
        var message = '<table class="table table-bordered" style="font-size:13px;">';
        message += '<thead style="background:#f0f4f8;">'
                 + '<tr>'
                 + '<th style="padding:8px;">Visited Date</th>'
                 + '<th style="padding:8px;">Days</th>'
                 + '<th style="padding:8px;">Next Visit Date</th>'
                 + '</tr></thead><tbody>';

        review_table.forEach(function(row) {
            message += '<tr>'
                + '<td style="padding:8px;">' + (row.visited_date  || '-') + '</td>'
                + '<td style="padding:8px;">' + (row.days          || '-') + '</td>'
                + '<td style="padding:8px;"><b style="color:green;">'
                + (row.next_visit_date || 'Not Set')
                + '</b></td>'
                + '</tr>';
        });

        message += '</tbody></table>';

        frappe.msgprint({
            title    : __('Patient Follow-up Schedule'),
            indicator: 'green',
            message  : message
        });

        // Send bell notification immediately on save
        review_table.forEach(function(row) {
            if (!row.next_visit_date) return;

            frappe.call({
                method: 'frappe.client.insert',
                args: {
                    doc: {
                        doctype       : 'Notification Log',
                        subject       : 'Follow-up Reminder - Patient: ' + frm.doc.name,
                        email_content : '<table border="1" cellpadding="8" cellspacing="0" style="font-size:13px;border-collapse:collapse;width:100%;">'
                                      + '<tr style="background:#f0f4f8;">'
                                      + '<th>Patient</th><th>Visited Date</th><th>Days</th><th>Next Visit Date</th>'
                                      + '</tr>'
                                      + '<tr>'
                                      + '<td>' + frm.doc.name            + '</td>'
                                      + '<td>' + (row.visited_date || '-') + '</td>'
                                      + '<td>' + (row.days         || '-') + '</td>'
                                      + '<td><b style="color:green;">' + row.next_visit_date + '</b></td>'
                                      + '</tr></table>',
                        for_user      : frappe.session.user,
                        type          : 'Alert',
                        document_type : 'Patient',
                        document_name : frm.doc.name
                    }
                },
                callback: function(r) {
                    if (!r.exc) {
                        frappe.show_alert({
                            message: '🔔 Follow-up reminder set for ' + row.next_visit_date,
                            indicator: 'green'
                        }, 5);
                    }
                }
            });
        });
    }
});

