function download_invoice_csv(frm) {
    const items = frm.doc.items || [];

    if (!items.length) {
        frappe.msgprint({
            title: __("No Items"),
            message: __("There are no items available to download."),
            indicator: "orange"
        });
        return;
    }

    const headers = [
        "Item Name",
        "Quantity",
        "Rate",
        "CGST Amount",
        "SGST Amount",
        "Total GST",
        "Amount"
    ];

    const rows = items.map(item => [
        item.item_name || item.item_code || "",
        flt(item.qty),
        flt(item.rate, 2).toFixed(2),
        flt(item.custom_cgst_amount, 2).toFixed(2),
        flt(item.custom_sgst_amount, 2).toFixed(2),
        flt(item.custom_total_gst, 2).toFixed(2),
        flt(item.amount, 2).toFixed(2)
    ]);

    const csv = [
        headers,
        ...rows
    ]
        .map(row =>
            row.map(value => {
                value = String(value ?? "");

                if (
                    value.includes(",") ||
                    value.includes('"') ||
                    value.includes("\n")
                ) {
                    value = '"' + value.replace(/"/g, '""') + '"';
                }

                return value;
            }).join(",")
        )
        .join("\r\n");

    const blob = new Blob(
        ["\uFEFF" + csv],
        {
            type: "text/csv;charset=utf-8;"
        }
    );

    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");

    link.href = url;
    link.download = "items-invoice.csv";

    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    setTimeout(() => {
        URL.revokeObjectURL(url);
    }, 100);
}

