function set_clinical_procedure_details(frm) {

    if (!frm.doc.custom_clinical_procedure) {
        clear_clinical_procedure_fields(frm);
        return;
    }

    frappe.db.get_value(
        "Clinical Procedure",
        frm.doc.custom_clinical_procedure,
        [
            "patient",
            "patient_name",
            "patient_sex",
            "patient_age",
            "inpatient_record",
            "company",
            "service_unit",
            "practitioner",
            "practitioner_name",
            "service_request"
        ]
    ).then(function(r) {

        if (!r || !r.message) {
            return;
        }

        var cp = r.message;

        // Clinical Procedure → Sales Invoice

        frm.set_value(
            "patient",
            cp.patient || ""
        );

        frm.set_value(
            "patient_name",
            cp.patient_name || ""
        );

        frm.set_value(
            "custom_gender",
            cp.patient_sex || ""
        );

        frm.set_value(
            "custom_inpatient_record",
            cp.inpatient_record || ""
        );

        frm.set_value(
            "company",
            cp.company || ""
        );

        frm.set_value(
            "service_unit",
            cp.service_unit || ""
        );

        frm.set_value(
            "ref_practitioner",
            cp.practitioner || ""
        );

        frm.set_value(
            "custom_doctor_name_",
            cp.practitioner_name || ""
        );


        // Get Patient information

        if (cp.patient) {

            frappe.db.get_value(
                "Patient",
                cp.patient,
                [
                    "customer",
                    "custom_age",
                    "custom_address"
                ]
            ).then(function(patient_result) {

                if (
                    patient_result &&
                    patient_result.message
                ) {

                    var patient = patient_result.message;

                    frm.set_value(
                        "customer",
                        patient.customer || ""
                    );

                    frm.set_value(
                        "custom_patient_age",
                        patient.custom_age || ""
                    );

                    frm.set_value(
                        "custom_address",
                        patient.custom_address || ""
                    );
                }
            });
        }


        // Get Patient Encounter from Service Request

        if (cp.service_request) {

            frappe.db.get_value(
                "Service Request",
                cp.service_request,
                [
                    "order_group",
                    "order_group_doctype"
                ]
            ).then(function(sr_result) {

                if (
                    sr_result &&
                    sr_result.message
                ) {

                    var sr = sr_result.message;

                    if (
                        sr.order_group_doctype ===
                            "Patient Encounter" &&
                        sr.order_group
                    ) {

                        frm.set_value(
                            "custom_perscription",
                            sr.order_group
                        );
                    }
                }
            });
        }

    });
}


