async function apply_healthcare_discount(frm) {
    if (frm.doc.docstatus !== 0) return;

    for (const row of (frm.doc.items || [])) {
        await apply_item_discount(frm, row.doctype, row.name);
    }

    update_overall_discount(frm);
}

async function apply_item_discount(frm, cdt, cdn) {
    if (frm.doc.docstatus !== 0) return;

    const row = locals[cdt]?.[cdn];
    if (!row || !row.item_code) return;

    const itemCode = row.item_code;
    let discount = 0;

    if (frm.doc.patient && !frm.doc.custom_inpatient_record) {
        const result = await frappe.db.get_value(
            "Item", itemCode, "item_group"
        );

        const currentRow = locals[cdt]?.[cdn];

        if (!currentRow || currentRow.item_code !== itemCode) return;

        if (result.message?.item_group !== "Consultation Charge") {
            discount = 5;
        }
    }

    await frappe.model.set_value(
        cdt, cdn, "discount_percentage", discount
    );

    update_overall_discount(frm);
}

function update_overall_discount(frm) {
    const totalDiscount = (frm.doc.items || []).reduce(
        (total, row) => total + flt(row.discount_amount),
