// Copy ERPNext's calculated CGST and SGST into custom fields.
function update_custom_gst(frm) {
    let cgst = 0;
    let sgst = 0;

    (frm.doc.taxes || []).forEach(row => {
        const account = (row.account_head || "").toLowerCase();
        const description = (row.description || "").toLowerCase();
        const amount = flt(row.tax_amount);

        if (account.includes("cgst") || description.includes("cgst")) {
            cgst += amount;
        }

        if (account.includes("sgst") || description.includes("sgst")) {
            sgst += amount;
        }
    });

    frm.set_value("custom_cgst", cgst);
    frm.set_value("custom_sgst", sgst);
    frm.set_value("custom_total_gst", cgst + sgst);
}

// Copy ERPNext's standard total advance into the custom field.
function update_custom_advance_amount(frm) {
    const totalAdvance = flt(frm.doc.total_advance);

    if (flt(frm.doc.custom_advance_amount) !== totalAdvance) {
        frm.set_value("custom_advance_amount", totalAdvance);
    }
}

function get_cash_balance(frm) {
    const total = flt(frm.doc.grand_total);
    const received = flt(frm.doc.custom_cash_received);
    const difference = received - total;

    return {
        balance: Math.abs(difference),
        label: difference > 0 ? "Change to Return" : "Amount Due",
        message: difference >= 0
            ? "Change to Return: " + format_currency(difference, frm.doc.currency)
            : "Amount Due: " + format_currency(Math.abs(difference), frm.doc.currency)
    };
}

function update_cash_balance_display(frm) {
    const result = get_cash_balance(frm);

    if (frm.fields_dict.custom_balance_amount) {
        frm.set_df_property(
            "custom_balance_amount",
            "label",
            result.label
        );
    }

    if (frm.fields_dict.custom_balance_) {
        frm.set_df_property(
            "custom_balance_",
            "description",
            result.message
        );
    }
}

function calculate_cash_balance(frm) {
    const result = get_cash_balance(frm);

    update_cash_balance_display(frm);

    if (flt(frm.doc.custom_balance_amount) !== result.balance) {
        frm.set_value("custom_balance_amount", result.balance);
    }

    if (frm.doc.custom_balance_ !== result.message) {
        frm.set_value("custom_balance_", result.message);
    }
}

