function calculate_cash_change(frm) {
    const tendered = flt(frm.doc.custom_cash_tendered);
    const received = flt(frm.doc.received_amount);

    const change = Math.max(tendered - received, 0);

    if (frm.doc.custom_change_to_return !== change) {
        frm.set_value("custom_change_to_return", change);
    }
}

function fu_add_months(date, months) {
    let result = new Date(date);
    let day = result.getDate();

    result.setDate(1);
    result.setMonth(result.getMonth() + months);

    let lastDay = new Date(
        result.getFullYear(),
        result.getMonth() + 1,
        0
    ).getDate();

    result.setDate(Math.min(day, lastDay));
    return result;
}

function fu_base(frm) {
    return frappe.datetime.str_to_obj(
        frm.doc.encounter_date || frappe.datetime.get_today()
    );
}

function fu_set_date(frm, unit) {
    let value = cint(frm.doc["custom_follow_up_" + unit]);
    if (value < 0) return;

    let base = fu_base(frm);
    let result;

    if (unit === "months") {
        result = fu_add_months(base, value);
    } else {
        result = new Date(base);
        result.setDate(
            result.getDate() + value * (unit === "weeks" ? 7 : 1)
        );
    }

    frm.__fu_updating_date = true;

    frm.set_value(
        "custom_follow_up_date",
        frappe.datetime.obj_to_str(result)
    ).then(() => {
        frm.__fu_updating_date = false;
    });
}

