const FREE_ZERO_FIELDS = [
    "rate",
    "amount",
    "custom_buy_rate",
    "custom_buy_amount",
    "custom_buy_net_amount_",
    "custom_cgst",
    "custom_sgst",
    "custom_gst"
];

function save_original_values(row) {
    if (row.__before_free_values) return;

    row.__before_free_values = {};

    FREE_ZERO_FIELDS.forEach(fieldname => {
        row.__before_free_values[fieldname] = flt(row[fieldname]);
    });
}

function apply_free_to_row(row) {
    if (!is_free_purchase_item(row)) return;

    save_original_values(row);

    FREE_ZERO_FIELDS.forEach(fieldname => {
        frappe.model.set_value(
            row.doctype,
            row.name,
            fieldname,
            0
        );
    });
}

function restore_purchase_values(row) {
    const original = row.__before_free_values;

    if (!original) {
        frappe.msgprint(
            "Original values are unavailable for this row. Re-select the item or enter its purchase values again."
        );
        return;
    }

    FREE_ZERO_FIELDS.forEach(fieldname => {
        frappe.model.set_value(
            row.doctype,
            row.name,
            fieldname,
            original[fieldname] ?? 0
        );
    });

    delete row.__before_free_values;
}

