function calculate_row(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    if (!row) return;

    if ((row.custom_type || "").trim() === "Free") {
        row.custom_buy_rate = 0;
        row.custom_buy_amount = 0;
        row.custom_buy_net_amount_ = 0;
        calculate_purchase_totals(frm);
        return;
    }

    const qty = flt(row.qty);
    const rate = flt(row.custom_buy_rate);
    const discount = flt(row.custom_buy_discount_);
    const gst = flt(row.custom_gst);

    const buy_amount = qty * rate;
    const discount_amount = buy_amount * discount / 100;
    const taxable_amount = buy_amount - discount_amount;
    const gst_amount = taxable_amount * gst / 100;
    const buy_net_amount = taxable_amount + gst_amount;

    frappe.model.set_value(cdt, cdn, "custom_buy_amount", buy_amount);
    frappe.model.set_value(cdt, cdn, "custom_buy_net_amount_", buy_net_amount);

    calculate_purchase_totals(frm);
}

function calculate_purchase_totals(frm) {
    let total_qty = 0;
    let buy_total = 0;
    let total_discount = 0;
    let total_gst = 0;
    let buy_net_total = 0;

    (frm.doc.items || []).forEach(row => {
        const isFree = (row.custom_type || "").trim() === "Free";
        const qty = flt(row.qty);
        const rate = isFree ? 0 : flt(row.custom_buy_rate);
        const discount = isFree ? 0 : flt(row.custom_buy_discount_);
        const gst = isFree ? 0 : flt(row.custom_gst);

        const buy_amount = qty * rate;
        const discount_amount = buy_amount * discount / 100;
        const taxable_amount = buy_amount - discount_amount;
        const gst_amount = taxable_amount * gst / 100;
        const buy_net_amount = taxable_amount + gst_amount;

        if (isFree) {
            row.custom_buy_rate = 0;
            row.custom_buy_amount = 0;
            row.custom_buy_net_amount_ = 0;
        } else {
            row.custom_buy_amount = buy_amount;
            row.custom_buy_net_amount_ = buy_net_amount;
        }

        total_qty += qty;
        buy_total += buy_amount;
        total_discount += discount_amount;
        total_gst += gst_amount;
        buy_net_total += buy_net_amount;
    });

    frm.set_value("total_qty", total_qty);
    frm.set_value("custom_buy_total", buy_total);
    frm.set_value("custom_total_discount", total_discount);
    frm.set_value("custom_total_gst", total_gst);
    frm.set_value("custom_buy_net_total_", buy_net_total);
}

