    FREE_ZERO_FIELDS.forEach(fieldname => {
        row.__before_free_values[fieldname] = flt(row[fieldname]);
    });
}

function apply_free_to_row(row) {
    if (!is_free_purchase_item(row)) return;

    save_original_values(row);

    FREE_ZERO_FIELDS.forEach(fieldname => {
        if (flt(row[fieldname]) !== 0) {
