}

function restore_purchase_values(row) {
    const original = row.__before_free_values;

    if (!original) {
        frappe.msgprint({
            title: "Original price unavailable",
            indicator: "orange",
            message: "The original values were not saved before the item became Free. Retrieve the original prices before continuing."
