async function fetch_party_from_inpatient(frm) {
    const inpatient_id = frm.doc.custom_inpatient_record;
    if (!inpatient_id) return;

    try {
        const ip_response = await frappe.db.get_value(
            "Inpatient Record",
            inpatient_id,
            "patient"
        );

        const patient_id = ip_response.message?.patient;

        if (!patient_id) {
            frappe.msgprint(
                "No Patient linked to Inpatient Record " + inpatient_id
            );
            return;
        }

        const patient_response = await frappe.db.get_value(
            "Patient",
            patient_id,
            ["customer", "patient_name"]
        );

        const patient = patient_response.message || {};
        const customer = patient.customer;

        if (!customer) {
            frappe.msgprint(
                "No Customer linked to Patient " + patient_id
            );
            return;
        }

        await frm.set_value("party_type", "Customer");
        await frm.set_value("party", customer);

        // Store the Patient's name in the standard Party Name field.
        await frm.set_value(
            "party_name",
            patient.patient_name || ""
        );

        console.log("Inpatient:", inpatient_id);
        console.log("Patient:", patient_id);
        console.log("Customer:", customer);

    } catch (error) {
        console.error("Failed to fetch party from Inpatient Record:", error);
        frappe.msgprint(
            "Could not fetch Patient and Customer details. Check the browser console."
        );
    }
}

