async function update_item_gst(frm, cdt, cdn) {
    const row = locals[cdt][cdn];

    if (!row || !row.item_code) return;

    const itemCode = row.item_code;

    const result = await frappe.db.get_value(
        "Item",
        itemCode,
        ["custom_cgst_", "custom_sgst_"]
    );

    const current = locals[cdt][cdn];

    if (!current || current.item_code !== itemCode) return;
    if (is_free_purchase_item(current)) return;

    const cgst = flt(result.message?.custom_cgst_);
    const sgst = flt(result.message?.custom_sgst_);

    if (flt(current.custom_cgst) !== cgst) {
        await frappe.model.set_value(
            cdt, cdn, "custom_cgst", cgst
        );
    }

    if (flt(current.custom_sgst) !== sgst) {
        await frappe.model.set_value(
            cdt, cdn, "custom_sgst", sgst
        );
    }

    const totalGst = cgst + sgst;

    if (flt(current.custom_gst) !== totalGst) {
        await frappe.model.set_value(
            cdt, cdn, "custom_gst", totalGst
        );
    }

    frm.refresh_field("items");
}

function set_parent_value_if_changed(frm, fieldname, value) {
    if (flt(frm.doc[fieldname]) !== flt(value)) {
        frm.set_value(fieldname, value);
    }
}

function calculate_row(frm, cdt, cdn) {
    const row = locals[cdt][cdn];

    if (!row) return;

    if (is_free_purchase_item(row)) {
        apply_free_to_row(row);
        calculate_purchase_totals(frm);
        return;
    }

    const qty = flt(row.qty);
    const rate = flt(row.custom_buy_rate);
    const discount = flt(row.custom_buy_discount_);
    const gst = flt(row.custom_gst);

    const buy_amount = qty * rate;
    const discount_amount = buy_amount * discount / 100;
    const taxable_amount = buy_amount - discount_amount;
    const gst_amount = taxable_amount * gst / 100;
    const buy_net_amount = taxable_amount + gst_amount;

    if (flt(row.custom_buy_amount) !== buy_amount) {
        frappe.model.set_value(
            cdt, cdn, "custom_buy_amount", buy_amount
        );
    }

    if (flt(row.custom_buy_net_amount_) !== buy_net_amount) {
        frappe.model.set_value(
            cdt, cdn, "custom_buy_net_amount_", buy_net_amount
        );
    }

    calculate_purchase_totals(frm);
}

function calculate_purchase_totals(frm) {
    let total_qty = 0;
    let buy_total = 0;
    let total_discount = 0;
    let total_gst = 0;
    let total_cgst = 0;
    let total_sgst = 0;
    let buy_net_total = 0;

    (frm.doc.items || []).forEach(row => {
        const isFree = is_free_purchase_item(row);

        const qty = flt(row.qty);
        const rate = isFree ? 0 : flt(row.custom_buy_rate);
        const discount = isFree ? 0 : flt(row.custom_buy_discount_);
        const gst = isFree ? 0 : flt(row.custom_gst);

        const buy_amount = qty * rate;
        const discount_amount = buy_amount * discount / 100;
        const taxable_amount = buy_amount - discount_amount;
        const gst_amount = taxable_amount * gst / 100;
        const buy_net_amount = taxable_amount + gst_amount;

        if (isFree) {
            row.custom_buy_rate = 0;
            row.custom_buy_amount = 0;
            row.custom_buy_net_amount_ = 0;
        } else {
            row.custom_buy_amount = buy_amount;
            row.custom_buy_net_amount_ = buy_net_amount;
        }

        total_qty += qty;
        buy_total += buy_amount;
        total_discount += discount_amount;
        total_gst += gst_amount;

        total_cgst += gst_amount / 2;
        total_sgst += gst_amount / 2;

        buy_net_total += buy_net_amount;
    });

    set_parent_value_if_changed(frm, "total_qty", total_qty);
    set_parent_value_if_changed(frm, "custom_buy_total", buy_total);
    set_parent_value_if_changed(frm, "custom_total_discount", total_discount);
    set_parent_value_if_changed(frm, "custom_cgst", total_cgst);
    set_parent_value_if_changed(frm, "custom_sgst", total_sgst);
    set_parent_value_if_changed(frm, "custom_total_gst", total_gst);
    set_parent_value_if_changed(frm, "custom_buy_net_total_", buy_net_total);
}


