function update_gst_summary(frm) {
    let cgst = 0;
    let sgst = 0;

    (frm.doc.taxes || []).forEach(tax => {
        const account = (tax.account_head || "").toUpperCase();

        if (account.includes("CGST")) {
            cgst += flt(tax.tax_amount);
        }

        if (account.includes("SGST")) {
            sgst += flt(tax.tax_amount);
        }
    });

    // Update values without marking the document as modified
    frm.doc.custom_cgst = cgst;
    frm.doc.custom_sgst = sgst;
    frm.doc.custom_total_gst = cgst + sgst;

    frm.refresh_field("custom_cgst");
    frm.refresh_field("custom_sgst");
    frm.refresh_field("custom_total_gst");
}

