frappe.ui.form.on("Medicine Return Item", {
    async item_code(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        const code = row.item_code;

        await frappe.model.set_value(cdt, cdn, {
            batch_no: "",
            expiry_date: "",
            mrp: 0,
            refund_amount: 0,
            valuation_rate: 0,
            serial_and_batch_bundle: "",
            warehouse: "Stores - SH"
        });

        if (!code) return;

        const item = await frappe.db.get_doc("Item", code);
        if (locals[cdt][cdn].item_code !== code) return;

        row.has_batch_no = item.has_batch_no;
        row.has_serial_no = item.has_serial_no;

        await frappe.model.set_value(
            cdt, cdn, "valuation_rate", flt(item.valuation_rate)
        );

        if (!item.has_batch_no && !item.has_serial_no) {
            const result = await frappe.db.get_value(
                "Item Price",
                {
                    item_code: code,
                    price_list: "Standard Selling"
                },
                "price_list_rate"
            );

            const mrp = flt(result.message?.price_list_rate);
            await frappe.model.set_value(cdt, cdn, {
                mrp,
                expiry_date: item.end_of_life || ""
            });

            calculate_row_refund(frm, cdt, cdn);
        }
    },

    pick_serial_and_batch(frm, cdt, cdn) {
        const row = locals[cdt][cdn];

        if (!row.item_code) {
            frappe.msgprint("Select a medicine first.");
            return;
        }

        if (!row.warehouse) {
            frappe.msgprint("Select a warehouse first.");
            return;
        }

        if (!row.has_batch_no && !row.has_serial_no) {
            frappe.msgprint("This item does not require batch or serial selection.");
            return;
        }

        row.type_of_transaction = "Inward";
        row.title = __("Select Batch No");

        new erpnext.SerialBatchPackageSelector(frm, row, async (result) => {
            if (!result) return;

            const entries = await frappe.db.get_list(
                "Serial and Batch Entry",
                {
                    filters: { parent: result.name },
                    fields: ["batch_no"],
                    limit: 100
                }
            );

            const batches = [...new Set(
                (entries || []).map(e => e.batch_no).filter(Boolean)
            )];

            if (batches.length > 1) {
                frappe.msgprint(
                    "Select one batch per return row. Add another row for another batch."
                );
                return;
            }

            if (batches.length === 1) {
                const batch = await frappe.db.get_value(
                    "Batch",
                    batches[0],
                    ["expiry_date", "custom_mrp"]
                );

                await frappe.model.set_value(cdt, cdn, {
                    batch_no: batches[0],
                    expiry_date: batch.message.expiry_date || "",
                    mrp: flt(batch.message.custom_mrp),
                    qty: Math.abs(flt(result.total_qty)),
                    serial_and_batch_bundle: result.name
                });
            } else {
                await frappe.model.set_value(cdt, cdn, {
                    qty: Math.abs(flt(result.total_qty)),
                    serial_and_batch_bundle: result.name
                });
            }

            calculate_row_refund(frm, cdt, cdn);
        });
    },

    batch_no: async function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (!row.batch_no) return;

        const batch = await frappe.db.get_doc("Batch", row.batch_no);

        await frappe.model.set_value(cdt, cdn, {
            expiry_date: batch.expiry_date || "",
            mrp: flt(batch.custom_mrp)
        });

        calculate_row_refund(frm, cdt, cdn);
    },

    mrp(frm, cdt, cdn) {
        calculate_row_refund(frm, cdt, cdn);
    },

    qty(frm, cdt, cdn) {
        calculate_row_refund(frm, cdt, cdn);
    }
});

function calculate_row_refund(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    frappe.model.set_value(
        cdt, cdn, "refund_amount",
        flt(row.mrp) * flt(row.qty)
    );
    calculate_total_refund(frm);
}

function calculate_total_refund(frm) {
    const total = (frm.doc.items || []).reduce(
        (sum, row) => sum + flt(row.refund_amount), 0
    );
    frm.set_value("total_refund", total);
}



frappe.ui.form.on("Medicine Return", {
    onload(frm) {
        if (frm.is_new()) {
            if (!frm.doc.refund_mode) {
                frm.set_value("refund_mode", "Cash");
            }

            if (!frm.doc.refund_account) {
                frm.set_value("refund_account", "Cash - SH");
            }
        }
    }
});



frappe.ui.form.on("Medicine Return", {
    onload_post_render(frm) {
        if (frm.is_new()) {
            frm.set_value("refund_account", null).then(() => {
                frm.set_value("refund_account", "Cash - SH");
            });
        }
    }
});




// Medicine Return - Available Stock
frappe.ui.form.on("Medicine Return Item", {
    item_code(frm, cdt, cdn) {
        const row = locals[cdt][cdn];

        if (!row.item_code) return;

        frappe.db.get_value("Item", row.item_code, "has_batch_no")
            .then(r => {
                if (r.message && r.message.has_batch_no) {
                    frappe.call({
                        method: "selvi_hospital.selvi_hospital_custom_app.doctype.medicine_return.medicine_return.get_medicine_return_batches",
                        args: { item_code: row.item_code },
                        callback(res) {
                            const batches = res.message || [];
                            const total = batches.reduce(
                                (sum, b) => sum + flt(b.available_qty), 0
                            );

                            frappe.model.set_value(
                                cdt, cdn, "custom_available_stock", total
                            );
                        }
                    });
                } else {
                    frappe.db.get_value("Bin", {
                        item_code: row.item_code,
                        warehouse: "Stores - SH"
                    }, "actual_qty").then(stock => {
                        frappe.model.set_value(
                            cdt, cdn, "custom_available_stock",
                            flt(stock.message?.actual_qty)
                        );
                    });
                }
            });
    },

    batch_no(frm, cdt, cdn) {
        const row = locals[cdt][cdn];

        if (!row.item_code || !row.batch_no) return;

        frappe.call({
            method: "selvi_hospital.selvi_hospital_custom_app.doctype.medicine_return.medicine_return.get_medicine_return_batches",
            args: { item_code: row.item_code },
            callback(res) {
                const batches = res.message || [];
                const selected = batches.find(
                    b => b.name === row.batch_no
                );

                frappe.model.set_value(
                    cdt, cdn, "custom_available_stock",
                    flt(selected?.available_qty)
                );
            }
        });
    }
});


// Patient ID -> Fetch and display Patient Name
frappe.ui.form.on("Medicine Return", {
    refresh(frm) {
        frm.toggle_display("patient_name", !!frm.doc.patient);
    },

    patient(frm) {
        if (!frm.doc.patient) {
            frm.set_value("patient_name", "");
            frm.toggle_display("patient_name", false);
            return;
        }

        frappe.db.get_value(
            "Patient",
            frm.doc.patient,
            "patient_name"
        ).then(r => {
            frm.set_value(
                "patient_name",
                r.message?.patient_name || ""
            );
            frm.toggle_display("patient_name", true);
        });
    }
});
